async def act(page):
    """
    Add a simple product named Energy-Bulk Women Shirt with price $60, qty=50,
    attributes Size=S and Color=Blue in Magento Admin.

    Strategy:
    - Use a relative goto to the Manage Products grid.
    - Use only accessibility-centric selectors (page.get_by_role, page.get_by_label, etc.).
    - Be tolerant of variations in labels by trying several plausible label names.
    - Make Save the final action (it may navigate / reload the page).
    """
    # Navigate to Manage Products grid using a relative URL
    await page.goto("/index.php/admin/catalog_product/index/")
    await page.wait_for_load_state("networkidle")

    # Click "Add Product" (try button then link)
    if await page.get_by_role("button", name="Add Product").count() > 0:
        await page.get_by_role("button", name="Add Product").click()
    elif await page.get_by_role("link", name="Add Product").count() > 0:
        await page.get_by_role("link", name="Add Product").click()
    else:
        # Some Magento installs show an Add Product drop-down; try a generic Add button
        if await page.get_by_role("button", name="Add").count() > 0:
            await page.get_by_role("button", name="Add").click()

    await page.wait_for_load_state("networkidle")

    # If product type/attribute set step appears, choose Simple Product and continue
    try:
        if await page.get_by_role("radio", name="Simple Product").count() > 0:
            await page.get_by_role("radio", name="Simple Product").check()
    except Exception:
        # ignore if not present
        pass

    # Click Continue if present
    if await page.get_by_role("button", name="Continue").count() > 0:
        await page.get_by_role("button", name="Continue").click()
        await page.wait_for_load_state("networkidle")

    # Fill product name (try multiple plausible labels)
    name_locators = ["Name", "Product Name"]
    for lbl in name_locators:
        if await page.get_by_label(lbl).count() > 0:
            await page.get_by_label(lbl).fill("Energy-Bulk Women Shirt")
            break

    # Fill price
    price_labels = ["Price", "Price (Excl. Tax)"]
    for lbl in price_labels:
        if await page.get_by_label(lbl).count() > 0:
            await page.get_by_label(lbl).fill("60")
            break

    # Ensure status = Enabled if there's a select/combobox labeled Status
    if await page.get_by_label("Status").count() > 0:
        try:
            await page.get_by_label("Status").select_option(label="Enabled")
        except Exception:
            # If it's a radio or other control, try to click an "Enabled" option
            if await page.get_by_role("radio", name="Enabled").count() > 0:
                await page.get_by_role("radio", name="Enabled").check()

    # Set attributes: Size -> S, Color -> Blue
    if await page.get_by_label("Size").count() > 0:
        try:
            await page.get_by_label("Size").select_option(label="S")
        except Exception:
            # if it's not a select, try a radio
            if await page.get_by_role("radio", name="S").count() > 0:
                await page.get_by_role("radio", name="S").check()

    # Color attribute
    if await page.get_by_label("Color").count() > 0:
        try:
            await page.get_by_label("Color").select_option(label="Blue")
        except Exception:
            if await page.get_by_role("radio", name="Blue").count() > 0:
                await page.get_by_role("radio", name="Blue").check()

    # Open Inventory tab/section (try a few accessible roles)
    if await page.get_by_role("link", name="Inventory").count() > 0:
        await page.get_by_role("link", name="Inventory").click()
    elif await page.get_by_role("tab", name="Inventory").count() > 0:
        await page.get_by_role("tab", name="Inventory").click()
    elif await page.get_by_role("button", name="Inventory").count() > 0:
        await page.get_by_role("button", name="Inventory").click()

    # Small wait to let inventory fields appear
    await page.wait_for_timeout(500)

    # Fill Qty (try common labels)
    qty_labels = ["Qty", "Quantity"]
    for lbl in qty_labels:
        if await page.get_by_label(lbl).count() > 0:
            await page.get_by_label(lbl).fill("50")
            break

    # Set Stock Availability / In Stock
    # Try select labeled "Stock Availability" then a radio named "In Stock"
    if await page.get_by_label("Stock Availability").count() > 0:
        try:
            await page.get_by_label("Stock Availability").select_option(label="In Stock")
        except Exception:
            # if not a select, try a radio
            if await page.get_by_role("radio", name="In Stock").count() > 0:
                await page.get_by_role("radio", name="In Stock").check()
    else:
        # try checkbox labeled In Stock
        if await page.get_by_label("In Stock").count() > 0:
            # get_by_label may return a checkbox; ensure checked
            try:
                cb = page.get_by_label("In Stock")
                if await cb.count() > 0:
                    # There is no .is_checked() on Locator in some Playwright versions; try check() to ensure it's checked
                    await cb.check()
            except Exception:
                pass

    # Finally, save the product (this likely navigates or reloads the page) - keep as last action
    if await page.get_by_role("button", name="Save").count() > 0:
        await page.get_by_role("button", name="Save").click()
    elif await page.get_by_role("button", name="Save and Continue Edit").count() > 0:
        # fallback to save-and-continue
        await page.get_by_role("button", name="Save and Continue Edit").click()

    # Wait a short time for save to be processed
    await page.wait_for_load_state("networkidle")

